import { flatten } from "flat";
import { JSONPropertySchema } from "./schemas/JSONPropertySchema.js";

export const detectChanges = async ({ before, after }) => {
  const detectedChanges = [];
  const beforeParsed = before?.data
    ? JSON.parse(new TextDecoder().decode(before.data))
    : {};
  const afterParsed = after?.data
    ? JSON.parse(new TextDecoder().decode(after.data))
    : {};
  const flattenedBefore = flatten(beforeParsed, { safe: true });
  const flattenedAfter = flatten(afterParsed, { safe: true });

  for (const key in flattenedBefore) {
    if (!(key in flattenedAfter)) {
      detectedChanges.push({
        schema: JSONPropertySchema,
        entity_id: key,
        snapshot: undefined,
      });
    } else if (
      JSON.stringify(flattenedBefore[key]) !== JSON.stringify(flattenedAfter[key])
    ) {
      detectedChanges.push({
        schema: JSONPropertySchema,
        entity_id: key,
        snapshot: {
          property: key,
          value: flattenedAfter[key],
        },
      });
    }
  }

  for (const key in flattenedAfter) {
    if (!(key in flattenedBefore)) {
      detectedChanges.push({
        schema: JSONPropertySchema,
        entity_id: key,
        snapshot: {
          property: key,
          value: flattenedAfter[key],
        },
      });
    }
  }

  return detectedChanges;
};

import { applyChanges } from "./applyChanges.js";
import { detectChanges } from "./detectChanges.js";

export const plugin = {
  key: "plugin_json",
  detectChangesGlob: "*.json",
  applyChanges,
  detectChanges,
};

export const JSONPropertySchema = {
  key: "lix_plugin_json_property",
  type: "json",
  schema: {
    type: "object",
    properties: {
      property: { type: "string" },
    },
    required: ["property"],
    additionalProperties: true,
  },
};

export declare const JSONPropertySchema: {
  readonly key: "lix_plugin_json_property";
  readonly type: "json";
  readonly schema: {
    readonly type: "object";
    readonly properties: {
      readonly property: {
        readonly type: "string";
      };
    };
    readonly required: readonly ["property"];
    readonly additionalProperties: true;
  };
};

import { changeIsLeafOf } from "@lix-js/sdk";
import { unflatten } from "flat";
import { JSONPropertySchema } from "./schemas/JSONPropertySchema.js";

export const applyChanges = async ({ lix, changes }) => {
  const leafChanges = [
    ...new Set(
      await Promise.all(
        changes.map(async (change) => {
          const leafChange = await lix.db
            .selectFrom("change")
            .where(changeIsLeafOf({ id: change.id }))
            .selectAll()
            .executeTakeFirst();
          return JSON.stringify(leafChange);
        }),
      ),
    ),
  ].map((value) => JSON.parse(value));

  const flattened = {};
  for (const change of leafChanges) {
    if (change.schema_key === JSONPropertySchema.key) {
      const snapshot = await lix.db
        .selectFrom("snapshot")
        .where("id", "=", change.snapshot_id)
        .selectAll()
        .executeTakeFirstOrThrow();
      flattened[change.entity_id] = snapshot.content?.value;
    }
  }

  return {
    fileData: new TextEncoder().encode(JSON.stringify(unflatten(flattened))),
  };
};

